    log(`part ${name}: ${r.placed} placed` + (carved.length ? ` (${carved.length} cut through earlier floors)` : "") +
      (r.refused ? `; REFUSED ${r.refused} writes into earlier parts (x,y,z wanted had: ${r.refusedAt.map((p) => `${p[0]},${p[1]},${p[2]} ${p[3]} ${p[4]}`).join("; ")})` : "") +
      (r.offPalette.length ? `; OFF-PALETTE: ${r.offPalette.join(", ")}` : ""));
    if (roof && reports.length === 1) r.offPalette.push(...layRoof(g, roof, owned, log, allowed, trussJob));   // the shell's to fix
  }
  for (const job of trussJob) {
    const { blocks, reports } = trussPlan(g, job);
    for (const [x, y, z, b, st] of blocks) g.set(x, y, z, b, st);
    const picks = reports.map((r) => r.pick ? `${r.pick.style} x${r.pick.trusses} every ${r.pick.spacing} m${r.pick.thick > 1 ? `, doubled` : ""} (worst member ${r.pick.util})` : "none passes").join("; ");
    log(`roof: ${blocks.length} truss blocks under the finished roof: ${picks} ($MCD trusses for the simulation)`);
  }
  if (report) writeFileSync(report, JSON.stringify(reports, null, 1));
  // $MCD_PARTS_CELLS=<file>: every part's cells, for measuring how much code each block cost (lab token audits)
  if (process.env.MCD_PARTS_CELLS) writeFileSync(process.env.MCD_PARTS_CELLS, JSON.stringify(cellsByPart));
  return reports;
}

// The roof from its spec on top of the shell, inside runParts: the cells it lays are locked like a part's; the shell
// cells it clears (above the eave) are freed for the parts that come after.
function layRoof(g, roof, owned, log, allowed, trussJob = []) {
  const spec = typeof roof === "string" ? (existsSync(roof) ? JSON.parse(readFileSync(roof, "utf8")) : null) : roof;
  if (!spec) { log(`roof: skipped, no ${roof} yet (the roof part writes it); every later part builds without it`); return []; }
  const before = new Map([...g].map((c) => [c.pos.join(","), c.block + JSON.stringify(c.state ?? {})]));
  const r = reroof(g, { ...spec, keep: spec.keep ?? [] });
  if (r.shift?.some(Boolean)) throw new Error(`roof: the overhang grew the site and moved every block by ${r.shift}; make the site larger so the roof fits`);
  // the roof's frame inside it ("trusses": true or { material, every, collar }, roof-trusses.mjs): framed after the
  // last part, under the finished roof (a part may still complete the ridge or a dormer), in the air that is left
  if (spec.trusses) {
    const T = spec.trusses === true ? {} : spec.trusses;
    const fp = spec.footprint, rects = !fp ? r.detected?.rects ?? [] : Array.isArray(fp[0]) ? fp : fp.from ? [[fp.from[0], fp.from[fp.from.length - 1], fp.to[0], fp.to[fp.to.length - 1]]] : [fp];
    trussJob.push({ footprint: rects, y: spec.y ?? r.detected?.y, ridgeAxis: spec.ridgeAxis, ...T });
  }
  let laid = 0, freed = 0;
  const off = new Map();
  for (const c of g) {
    const k = c.pos.join(",");
    if (before.get(k) !== c.block + JSON.stringify(c.state ?? {})) {
      owned.add(k); laid++;
      if (allowed && !allowed.has(ns(c.block))) off.set(ns(c.block), (off.get(ns(c.block)) ?? 0) + 1);
    }
    before.delete(k);
  }
  for (const k of before.keys()) if (owned.delete(k)) freed++;                 // cleared by the roof: open for later parts
  log(`roof: ${laid} placed (${spec.preset ?? spec.style ?? "roof"}), ${freed} shell cells above the eave cleared${r.refused ? `, ${r.refused} kept` : ""}` +
    (off.size ? `; OFF-PALETTE: ${[...off].map(([b, n]) => `${b.replace("minecraft:", "")} x${n}`).join(", ")} (fix roof.json)` : ""));
  return [...off].map(([b, n]) => `${b.replace("minecraft:", "")} x${n} (roof.json)`);
}

// ---- shape brushes (curved forms; massing) — the model picks parameters, code draws the form ---------------------
export * from "./shapes-curved.mjs";
export * from "./shapes-massing.mjs";

// ---- landscaping brushes (terrain, strata, boulders, water, trees, paths, bridges) — see references/landscaping.md --
export * from "./terrain.mjs";

// ---- roofs by style name (gable, hip, pyramid, mansard, gambrel, flat-parapet, shed, dutch-gable) — references/roofs.md
export * from "./roofs.mjs";

// ---- facade brushes (signage, pilasters, surrounds, glazing, fixtures, planters) — references/detail-language.md -----
// Each is a function on a grid (writes only where it may: air for projections, plain wall for in-place trim; returns
// { cells, skipped, notes, info }) and a B.* twin that returns the plan as g.set argument lists, unchecked.
// at = a wall cell (bottom-left of the band / opening as seen from outside), face = the side it looks out of.
import { commitGrid, lookGrid, tuples } from "./brush-core.mjs";
import { plaquePlan, signboardPlan, buntingPlan, bannerWordPlan } from "./brush-sign.mjs";
import { clockPlan } from "./brush-clock.mjs";
export { trussPlan } from "./roof-trusses.mjs";
import { pilasterPlan } from "./brush-pilaster.mjs";
import { surroundPlan, glazingPlan } from "./brush-surround.mjs";
import { fixturePlan, planterPlan } from "./brush-fixture.mjs";
const withLook = (g, o) => ({ ...o, look: lookGrid(g), dataVersion: o?.dataVersion ?? g.dataVersion });
/** Lettering in a band: plaque(g, "LEAGUE HALL", { at, face, width, height, letter?, material?, frame?, style?, relief? }) */
export const plaque = (g, text, o) => commitGrid(g, plaquePlan(text, withLook(g, o)), o);
const STEP = { north: [0, -1], south: [0, 1], east: [1, 0], west: [-1, 0] };
/** A bed, both halves: foot at [x,y,z], the head one step toward facing (the pillow end), same colour and facing. */
export const bed = (g, [x, y, z], facing, color = "red") => {
  const [dx, dz] = STEP[facing] ?? STEP.north, b = `${color}_bed`;
  g.set(x, y, z, b, { facing, part: "foot", occupied: "false" });
  g.set(x + dx, y, z + dz, b, { facing, part: "head", occupied: "false" });
};
/** A window shutter: an open trapdoor in the cell in front of the wall (on the face side), lying flat against it.
 *  face: the way the wall looks (north for a north front); the trapdoor's facing is the face, so it lies on the wall. */
export const shutter = (g, [x, y, z], face, wood = "spruce", { height = 1 } = {}) => {
  for (let i = 0; i < height; i++) g.set(x, y + i, z, `${wood}_trapdoor`, { facing: face, half: "bottom", open: "true", powered: "false", waterlogged: "false" });
};
/** A word in banner letters hung on a board, in reading order for its face: bannerWord(g, "BUTCHER", { center: [14, 10, 4], face: "north" }). */
export const bannerWord = (g, word, o) => { let n = 0; for (const [x, y, z, ...b] of bannerWordPlan(word, { ...o, banner: B.banner })) if (!g.get(x, y, z) || /air$/.test(g.get(x, y, z).block)) { g.set(x, y, z, ...b); n++; } return n; };
/** Redstone shop sockets: layoutSockets({ face, at, floorY, units: "DS DS", rows }) -> the layout (as sockets.json) */
export { layoutSockets };
/** The sockets' fit-out (glass wall lines and back walls, spawn-proof pit floor, counters): fitSockets(g, layout, { counter, glass }) */
export const fitSockets = (g, layout, o) => { const t = socketFitout(layout, o); for (const c of t) g.set(...c); return t.length; };
/** A clock face on a tower: clock(g, { center, face, radius?: 2-4, dial?, bezel?, hands?, time?: "10:10", out?: 0|1 }) */
export const clock = (g, o) => commitGrid(g, clockPlan(withLook(g, o)), o);
/** A shop sign: signboard(g, "BAKERY", { at, face, mode: "wall"|"hanging", width?, height?, wood? }) */
export const signboard = (g, text, o) => commitGrid(g, signboardPlan(text, withLook(g, o)), o);
/** Banners along a row: bunting(g, { from, to, face, colors?, every?, pattern? }) */
export const bunting = (g, o) => commitGrid(g, buntingPlan(withLook(g, o)), o);
/** A profiled pilaster: pilaster(g, { at, face, height, width?, out?, material?, profile?, shoulder? }) */
export const pilaster = (g, o) => commitGrid(g, pilasterPlan(o), o);
/** An opening surround: surround(g, { at, face, width, height, preset?, trim?, keystone?, reveal?, door?, arch? }) */
export const surround = (g, o) => commitGrid(g, surroundPlan(withLook(g, o)), o);
/** Glazing: glazing(g, { at, face, width, height, preset: grid|shopfront|transom|sidelights, frame?, door? }) */
export const glazing = (g, o) => commitGrid(g, glazingPlan(withLook(g, o)), o);
/** A light fitting: fixture(g, { at, face, mount: bracket|arm|top|hang, lamp? }) */
export const fixture = (g, o) => commitGrid(g, fixturePlan(withLook(g, o)), o);
/** A planter: planter(g, { at, face, width, kind: box|ground, depth?, plants? }) */
export const planter = (g, o) => commitGrid(g, planterPlan(withLook(g, o)), o);
Object.assign(B, {
  plaque: (text, o) => tuples(plaquePlan(text, o)), clock: (o) => tuples(clockPlan(o)), signboard: (text, o) => tuples(signboardPlan(text, o)), bunting: (o) => tuples(buntingPlan(o)),
  pilaster: (o) => tuples(pilasterPlan(o)), surround: (o) => tuples(surroundPlan(o)), glazing: (o) => tuples(glazingPlan(o)),
  fixture: (o) => tuples(fixturePlan(o)), planter: (o) => tuples(planterPlan(o)),
});
/** Run detail-language rules from code (weather / vary presets, treatments on every opening): returns { grid, report }. */
export { applyDetail as paint } from "./detail-lang.mjs";

