  for (let dx = -1; dx <= 2; dx++) for (let dz = -1; dz <= 2; dz++) {
    if (dx >= 0 && dx <= 1 && dz >= 0 && dz <= 1) continue;
    // the lip points out: facing = the direction into the wall (north and south rows take the corners)
