    n += dx === 0 && dz === 0
      ? put(g, x, capY, z, "hay_block", { axis: "y" })
      : put(g, x + dx, capY, z + dz, "brick_slab", { type: "bottom", waterlogged: "false" });
  }
  return n + put(g, x, capY + 1, z, "campfire", { facing: "north", lit: "true", signal_fire: "true", waterlogged: "false" });
